assignments.value:
={{ 
  (() => {
    // 1. 取得原始 text 字串
    const rawText = $json.candidates[0].content.parts[0].text;

    // 2. 解析 JSON
    const parsed = JSON.parse(rawText);

    // 3. 判斷解析後是否為陣列，若是則取第一個元素，若否則直接回傳
    return Array.isArray(parsed) ? parsed[0] : parsed;
  })()
}}

